{
  "case_id": "xsu_sg_001_general_conditions",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret nævner de tre kritiske betingelser fra rubrikken: SU/slutlån, videregående uddannelse eller dansk EUD, og varig funktionsnedsættelse med meget betydelige begrænsninger i erhvervsevnen. Det fremstiller ikke tillægget som selvstændigt, og det lader ikke en diagnose alene udløse ret. Der er mindre skævheder: 'fire hovedkrav' mod de tre i vejledningens afsnit 3.1, og 'samlet vurdering' af flere funktionsnedsættelser. Ingen af dem rammer de væsentlige fejl i rubrikken."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle tre kritiske elementer er med: SU/slutlån (tillægget gives sammen med SU-stipendium eller slutlån), indskrevet på videregående uddannelse eller dansk EUD, og varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde. De understøttende elementer (EUX, udenlandsk erhvervslignende uddannelse) mangler, men de er ikke kritiske."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret oplister betingelserne for SU-handicaptillæg og besvarer dermed spørgsmålet direkte. Den praktiske del om dokumentation og fornyet ansøgning er relevant og erstatter ikke noget svar."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til identificerbare kilder: vejledning nr. 10157, SU-bekendtgørelsen og Ankenævnets afgørelser. Henvisningerne er nummereret, og kildelisten er ufuldstændigt koblet til numrene, men kilderne kan identificeres."
    },
    "c05_source_validity": {
      "label": "not_met",
      "reason": "Vejledning nr. 10157 og SU-bekendtgørelsen er gyldige og aktuelle. Svaret støtter sig dog også på Ankenævnets afgørelser fra 2013-2014 og en 'KEN nr. 9942 af 2013'. De ligger uden for den frosne aktuelle kildeafgrænsning og kan ikke verificeres som aktuelle og anvendelige. Ét kildenummer er desuden vagt angivet ('Dokumentafsnit 289')."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Flere påstande støttes ikke af de udleverede passager. Det gælder 'fire hovedkrav' inkl. 'særlige krav til visse ikke-danske statsborgere', som afviger fra de tre betingelser i afsnit 3.1. Det gælder også kravet om at have modtaget SU i perioden, 'typiske studenterjobs', 'stort set ikke muligt at påtage sig arbejde i nævneværdigt omfang', 'samlet vurdering' af flere funktionsnedsættelser, og at midlertidig uarbejdsdygtighed ikke er nok. Dermed er ikke alle væsentlige påstande dækket."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer regler og tærskler uden støtte i det frosne materiale: krav til ikke-danske statsborgere, vurdering ud fra studenterjobs og at studierelevans og geografi ikke indgår, 'stort set ikke muligt'-tærsklen, samlet vurdering af flere funktionsnedsættelser og 'søge igen ved væsentlig ændring'. Den samlede vurdering står desuden i spænding med § 37, stk. 2, hvor retten vurderes ud fra de konkrete funktionsnedsættelser."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer 'kun' (UDK kan kun tildele til videregående uddannelse eller dansk EUD), at funktionsnedsættelsen skal være varig, og at almindelig sygdom 'normalt' ikke er nok. Rubrikken kræver ikke en standardadvarsel om, at de almindelige SU-betingelser ikke er udtømmende gengivet."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Strukturen er overvejende sammenhængende, og konklusionen følger af de opstillede betingelser. Der er små uoverensstemmelser: 'fire hovedkrav' passer ikke til de fem nummererede afsnit, og spændingen mellem samlet vurdering og konkret tilknytning er ikke afklaret. Det ændrer ikke konklusionen."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal', 'kan kun' og 'normalt' bruges overvejende i overensstemmelse med kilderne. Svaret skriver 'modtager SU' og 'har modtaget SU' i stedet for 'har ret til SU'. Det er en lille skærpelse, men svaret gør ikke skøn eller undtagelser absolutte på en måde, der ændrer betydningen."
    }
  },
  "xhaile_coverage": {
    "A1": {
      "label": "yes",
      "reason": "Svaret kræver ret til og modtagelse af SU eller slutlån og nævner de almindelige betingelser, og at tillægget gives sammen med SU-stipendium eller slutlån."
    },
    "A2": {
      "label": "yes",
      "reason": "Svaret kræver indskrivning på og gennemførelse af en videregående uddannelse eller dansk EUD."
    },
    "A3": {
      "label": "yes",
      "reason": "Svaret angiver kravet om varig fysisk eller psykisk funktionsnedsættelse med meget betydelige begrænsninger i evnen til at påtage sig erhvervsarbejde."
    },
    "A4": {
      "label": "partial",
      "reason": "Svaret kræver berettigelse til SU, men angiver ikke, at man skal være indskrevet på og gennemgå en uddannelse, der berettiger til SU eller slutlån, efter SU-lovens §§ 2-2 b."
    },
    "A6": {
      "label": "partial",
      "reason": "Dansk EUD er nævnt som omfattet uddannelse. Svaret nævner ikke, at EUX er omfattet, eller at erhvervslignende uddannelse i udlandet ikke er omfattet."
    }
  },
  "overall_notes": "Kernen i svaret er juridisk korrekt og dækker de tre kritiske betingelser. Det mangler EUX og udlandsafgrænsningen. Svaret er svagt på kildegrundlag, fordi flere påstande ikke kan støttes af de frosne passager: 'fire hovedkrav', statsborgerkrav, studenterjob-test, 'stort set ikke muligt', samlet vurdering og fornyet ansøgning. Svaret bruger også ældre Ankenævnsafgørelser uden for den frosne kildeafgrænsning. Det giver not_met på C05, C06 og C07."
}

